-- PostTags as SEDE derives it: one row per tag of a question, the tag found by its name.
-- The converter writes Posts.Tags in the spelling of SEDE, <tag><tag>, whatever the dump's.
SELECT DISTINCT p.[Id], t.[Id]
FROM [{{schema}}].[Posts] p
CROSS APPLY STRING_SPLIT(REPLACE(REPLACE(p.[Tags], '><', ','), '<', ''), ',') s
INNER JOIN [{{schema}}].[Tags] t ON t.[TagName] = REPLACE(s.[value], '>', '')
WHERE p.[Tags] IS NOT NULL;
GO

